const __pageData = JSON.parse('{"title":"登录功能","description":"第 12 章（登录认证）的开篇——先把「怎么样才算登录成功」和「登录的本质就是一次查询」想清楚，再按三层架构把登录接口落地（控制层收用户名密码、业务层查员工并生成令牌组装返回、数据访问层一条 select），最后照接口文档联调，实测登录成功与密码错误两种响应，并暴露「未登录也能直接访问所有接口」这个问题","frontmatter":{"title":"登录功能","published":"2026-09-29T00:00:00.000Z","description":"第 12 章（登录认证）的开篇——先把「怎么样才算登录成功」和「登录的本质就是一次查询」想清楚，再按三层架构把登录接口落地（控制层收用户名密码、业务层查员工并生成令牌组装返回、数据访问层一条 select），最后照接口文档联调，实测登录成功与密码错误两种响应，并暴露「未登录也能直接访问所有接口」这个问题","tags":["JavaWeb","后端","SpringBoot"],"image":"https://img.tsh520.cn/file/blog/post-covers/javaweb-81-login-function.webp","order":81,"date":"2026-09-29T00:00:00.000Z","cover":false,"hidden":true},"headers":[],"relativePath":"posts/学习文档/JavaWeb学习笔记/81-登录功能.md","filePath":"posts/学习文档/JavaWeb学习笔记/81-登录功能.md"}');
